svg.script:

(function() {
  // DICIONARIO COMPLETO DE DADOS ANATOMICOS E ANCORAGEM CLINICA
  var DB = {
    "sinfise": {
      title: "Sínfise Púbica e Ramos Púbicos",
      color: "var(--a12p22b-osso)",
      nivel: "ÂNCORA ÓSSEA",
      d1: "Camada: Arcabouço Ósseo Anterior da Pelve.",
      d2: "Ponto de inserção anterior do diafragma pélvico e urogenital.",
      d3: "Resiste às forças de tração do arco tendíneo da fáscia pélvica.",
      d4: "Referência anterior fundamental para medidas do prolapso.",
      a1: "\"A sínfise púbica fixa a borda anterior do hiato.\"",
      a2: "A desancoragem anterior compromete a sustentação uretro-vesical",
      a3: "e provoca hipermotilidade uretral com incontinência aos esforços."
    },
    "fascia-endopelvica": {
      title: "Fáscia Endopélvica (Rede Visceral)",
      color: "var(--a12p22b-fascia)",
      nivel: "NÍVEL I (DeLancey)",
      d1: "Camada: Tecido Conjuntivo Subperitoneal Profundo.",
      d2: "Envolve as vísceras pélvicas e fixa a cúpula vaginal.",
      d3: "Forma os eixos ligamentares vesicouterino, cardinal e uterossacro.",
      d4: "Transmite cargas viscerais diretamente ao arco tendíneo.",
      a1: "\"O Nível I é a suspensão apical da pelve.\"",
      a2: "Defeitos isolados no Nível I provocam prolapso de cúpula",
      a3: "ou uterino severo quando o diafragma pélvico atrofia."
    },
    "pubovesico": {
      title: "Ligamento Pubovesicouterino",
      color: "var(--a12p22b-suspensao)",
      nivel: "NÍVEL I / II",
      d1: "Camada: Condensação Anterior da Fáscia Endopélvica.",
      d2: "Conecta a parede vesical anterior e colo uterino ao púbis.",
      d3: "Estabiliza o colo vesical durante o aumento da pressão abdominal.",
      d4: "Impede a rotação posterior e o descenso do trígono.",
      a1: "\"Trava anterior do colo vesical e parede anterior.\"",
      a2: "A avulção pubovesical é causa direta de cistocele",
      a3: "por defeito de fixação anterior no arco tendíneo."
    },
    "cardinal": {
      title: "Ligamento Cardinal (Mackenrodt)",
      color: "var(--a12p22b-suspensao)",
      nivel: "NÍVEL I (Fora do Plano)",
      d1: "Camada: Condensação Lateral do Paramétrio / Paracólpio.",
      d2: "Transcorre lateralmente da parede pélvica ao colo uterino.",
      d3: "Indicado com padrão hachurado por estar fora do plano mediano exato.",
      d4: "Suporta a maior carga de tração vertical do útero.",
      a1: "\"O pilar lateral de sustentação apical.\"",
      a2: "Sua secção na histerectomia exige reancoragem rigorosa",
      a3: "na cúpula vaginal para evitar eversão pós-operatória."
    },
    "uterossacro": {
      title: "Ligamentos Uterossacros",
      color: "var(--a12p22b-suspensao)",
      nivel: "NÍVEL I (Posterior)",
      d1: "Camada: Condensação Posterior do Paramétrio.",
      d2: "Tracionam o colo uterino póstero-superiormente em direção ao sacro.",
      d3: "Mantêm o útero em anteversoflexão fisiológica.",
      d4: "Servem de eixo axial primário na cirurgia de reconstrução.",
      a1: "\"Direcionam o colo póstero-superiormente ao sacro.\"",
      a2: "A integridade dos uterossacros previne que a força",
      a3: "intra-abdominal incida diretamente sobre o hiato genital."
    },
    "pubococcigeo": {
      title: "Músculo Pubococcígeo",
      color: "var(--a12p22b-diafragma)",
      nivel: "NÍVEL II (Diafragma Pélvico)",
      d1: "Camada: Placa Central do Músculo Levantador do Ânus.",
      d2: "Origina-se no corpo do púbis e insere-se no cóccix e rafe anal.",
      d3: "Forma a prancha horizontal que suporta as vísceras pélvicas.",
      d4: "Eleva o assoalho pélvico na contração voluntária.",
      a1: "\"A prancha sustentadora da cavidade pélvica.\"",
      a2: "O estiramento excessivo no parto enfraquece a prancha",
      a3: "e inclina a placa levantadora, favorecendo a descendência."
    },
    "puborretal": {
      title: "Músculo Puborretal (Alça Pélvica)",
      color: "var(--a12p22b-diafragma)",
      nivel: "NÍVEL II (Diafragma Pélvico)",
      d1: "Camada: Componente Medial do Músculo Levantador do Ânus.",
      d2: "Forma alça muscular em U ancorada na sínfise púbica.",
      d3: "MANTÉM o ângulo anorretal e a continência fecal.",
      d4: "Tonus permanente garante fechamento do hiato urogenital.",
      a1: "\"O puborretal é o guardião dinâmico do hiato.\"",
      a2: "A avulção no parto vaginal amplia o hiato pélvico e",
      a3: "predispõe diretamente ao prolapso de órgãos pélvicos (POP)."
    },
    "iliococcigeo": {
      title: "Músculo Iliococcígeo",
      color: "var(--a12p22b-diafragma)",
      nivel: "NÍVEL II (Diafragma Pélvico)",
      d1: "Camada: Porção Póstero-Lateral do Levantador do Ânus.",
      d2: "Origina-se no arco tendíneo da fáscia obturatória.",
      d3: "Insere-se na borda lateral do cóccix e rafe anococcígea.",
      d4: "Fecha a porção posterior do hiato pélvico.",
      a1: "\"Fechamento póstero-lateral do hiato abdominal.\"",
      a2: "Proporciona base de apoio estável para a lâmina de",
      a3: "fáscia endopélvica e impede a herniação posterior."
    },
    "coccigeo": {
      title: "Músculo Coccígeo (Isquiococcígeo)",
      color: "var(--a12p22b-diafragma)",
      nivel: "NÍVEL II (Posterior)",
      d1: "Camada: Porção Posterior do Diafragma Pélvico.",
      d2: "Disposto sobre a superfície anterior do ligamento sacroespinhoso.",
      d3: "Conecta a espinha isquiática às margens do sacro e cóccix.",
      d4: "Estabiliza a articulação sacroilíaca e o cóccix.",
      a1: "\"Estabilizador muscular do ligamento sacroespinhoso.\"",
      a2: "Sua identificação palpatória orienta a fixação",
      a3: "de cúpula ao ligamento sacroespinhoso na cirurgia de POP."
    },
    "membrana-perineal": {
      title: "Membrana Perineal e Espaço Profundo",
      color: "var(--a12p22b-membrana)",
      nivel: "NÍVEL III / II",
      d1: "Camada: Lâmina Fibromuscular Triangular Anterior.",
      d2: "Ocupa o arco púbico e separa o espaço profundo do superficial.",
      d3: "Atravessada pela uretra e pela vagina.",
      d4: "Ancora o corpo perineal e os corpos cavernosos.",
      a1: "\"A plataforma de fixação inferior dos órgãos urogenitais.\"",
      a2: "Sua rotura transversal desancora o diafragma urogenital",
      a3: "provocando hipermotilidade e rectocele baixa."
    },
    "esfincter-uretral": {
      title: "Esfíncter Uretral Externo",
      color: "var(--a12p22b-membrana)",
      nivel: "NÍVEL III (Esfincteriano)",
      d1: "Camada: Espaço Perineal Profundo.",
      d2: "Envolve a uretra membranosa com fibras circulares e em alça.",
      d3: "Garante a continência urinária voluntária sob estresse.",
      d4: "Inervado pelo nervo pudendo (S2-S4).",
      a1: "\"Controle esfincteriano voluntário de alta pressão.\"",
      a2: "Lesões cirúrgicas ou obstétricas levam à perda do selamento",
      a3: "mucoso e incontinência urinária de esforço severa."
    },
    "transverso-profundo": {
      title: "Músculo Transverso Profundo do Períneo",
      color: "var(--a12p22b-membrana)",
      nivel: "NÍVEL III (Profundo)",
      d1: "Camada: Espaço Perineal Profundo.",
      d2: "Origina-se no ramo isquiopúbico e insere-se no corpo perineal.",
      d3: "Estabiliza o centro tendíneo do períneo no plano horizontal.",
      d4: "Dá suporte à membrana perineal.",
      a1: "\"Tensionador horizontal do corpo perineal profundo.\"",
      a2: "Sua integridade evita o afastamento dos ramos púbicos",
      a3: "e o colapso do diâmetro transverso do triângulo anterior."
    },
    "isquiocavernoso": {
      title: "Músculos Isquiocavernosos",
      color: "var(--a12p22b-perineo)",
      nivel: "NÍVEL III (Superficial)",
      d1: "Camada: Espaço Perineal Superficial.",
      d2: "Recobrem os ramos dos corpos cavernosos e pilares do clitóris.",
      d3: "Fixam-se na tuberosidade e ramo isquiopúbico.",
      d4: "Comprimem os pilares para manutenção da ereção.",
      a1: "\"Fixadores laterais dos corpos cavernosos nos ramos.\"",
      a2: "Estabilizan a genitália externa no arco anterior",
      a3: "durante a tração biomecânica e o esforço vaginal."
    },
    "bulboesponjoso": {
      title: "Músculo Bulboesponjoso / Bulbocavernoso",
      color: "var(--a12p22b-perineo)",
      nivel: "NÍVEL III (Superficial)",
      d1: "Camada: Espaço Perineal Superficial.",
      d2: "Envolve o óstio vaginal e os bulbos do vestíbulo.",
      d3: "Insere-se anterior ao clitóris e posterior ao corpo perineal.",
      d4: "Atua como esfíncter do intrito vaginal.",
      a1: "\"Constritor voluntário do intrito vaginal.\"",
      a2: "A laceração de 2º grau afeta diretamente este músculo,",
      a3: "exigindo reconstituição anatômica para evitar intrito entreaberto."
    },
    "transverso-superficial": {
      title: "Músculo Transverso Superficial do Períneo",
      color: "var(--a12p22b-perineo)",
      nivel: "NÍVEL III (Superficial)",
      d1: "Camada: Espaço Perineal Superficial.",
      d2: "Faixa muscular estreita que cruza anterior ao ânus.",
      d3: "Fixa a tuberosidade isquiática ao corpo perineal.",
      d4: "Estabiliza o centro tendíneo do períneo.",
      a1: "\"Âncora transversal do corpo perineal superficial.\"",
      a2: "Sua secção na episiotomia mediolateral requer aproximação",
      a3: "precisa para manter a simetria da fenda vulvar."
    },
    "esfincter-anal": {
      title: "Esfíncter Externo do Ânus",
      color: "var(--a12p22b-perineo)",
      nivel: "NÍVEL III (Posterior)",
      d1: "Camada: Espaço Perineal Superficial Posterior.",
      d2: "Anel muscular estriado voluntário ao redor do canal anal.",
      d3: "Ancorado no corpo perineal anterior e lig. anococcígeo.",
      d4: "Essencial para a continência fecal a altas pressões.",
      a1: "\"Controle fecal voluntário e âncora do corpo perineal.\"",
      a2: "Lacerações obstétricas de 3º e 4º graus seccionam o esfíncter,",
      a3: "exigindo sutura por sobreposição (overlapping) imediata."
    },
    "espinha": {
      title: "Espinhas Isquiáticas (Bilateral)",
      color: "var(--a12p22b-osso)",
      nivel: "ÂNCORA ÓSSEA",
      d1: "Camada: Arcabouço Ósseo Lateral.",
      d2: "Ponto de ancoragem dos ligamentos sacroespinhoso e coccígeo.",
      d3: "Demarca a transição entre o hiato pélvico e o forame isquiático.",
      d4: "Referência zero para a classificação POP-Q.",
      a1: "\"A referência anatômica central da pelve.\"",
      a2: "O plano das espinhas (estágio 0) é a linha de base para",
      a3: "mensuração de todos os prolapsos de órgãos pélvicos."
    },
    "coccix": {
      title: "Cóccix e Promontório Sacro",
      color: "var(--a12p22b-osso)",
      nivel: "ÂNCORA ÓSSEA",
      d1: "Camada: Arcabouço Ósseo Posterior.",
      d2: "Ponto de inserção da rafe anococcígea e m. pubococcígeo.",
      d3: "Recebe a tração posterior do ligamento uterossacro.",
      d4: "Ancora o vértice inferior da prancha levantadora.",
      a1: "\"Ancoragem posterior da placa do levantador.\"",
      a2: "Proporciona o contra-apoio dorsal necessário para que",
      a3: "a contração muscular eleve as vísceras para frente e para cima."
    }
  };

  var activeId = "puborretal";

  function updatePanel(id) {
    var data = DB[id];
    if (!data) return;
    activeId = id;

    // ATUALIZA ELEMENTOS DO PAINEL DE LEITURA
    var tTitle = document.getElementById("a12p22b-panel-title");
    var tNivel = document.getElementById("a12p22b-txt-nivel");
    var bgNivel = document.getElementById("a12p22b-tag-nivel");

    var d1 = document.getElementById("a12p22b-panel-desc1");
    var d2 = document.getElementById("a12p22b-panel-desc2");
    var d3 = document.getElementById("a12p22b-panel-desc3");
    var d4 = document.getElementById("a12p22b-panel-desc4");

    var a1 = document.getElementById("a12p22b-panel-anchor1");
    var a2 = document.getElementById("a12p22b-panel-anchor2");
    var a3 = document.getElementById("a12p22b-panel-anchor3");

    if (tTitle) {
      tTitle.textContent = data.title;
      tTitle.setAttribute("fill", data.color);
    }
    if (tNivel) tNivel.textContent = data.nivel;
    if (bgNivel) bgNivel.setAttribute("fill", data.color);

    if (d1) d1.textContent = data.d1;
    if (d2) d2.textContent = data.d2;
    if (d3) d3.textContent = data.d3;
    if (d4) d4.textContent = data.d4;

    if (a1) a1.textContent = data.a1;
    if (a2) a2.textContent = data.a2;
    if (a3) a3.textContent = data.a3;

    // ATUALIZA DESTAQUES NAS ESTRUTURAS DO STAGE
    var allHs = document.querySelectorAll("#a12p22b-svg .a12p22b-hs");
    for (var i = 0; i < allHs.length; i++) {
      var el = allHs[i];
      if (el.getAttribute("data-id") === id) {
        el.classList.add("is-active");
        el.setAttribute("stroke-width", "3.5");
        el.setAttribute("opacity", "1");
      } else {
        el.classList.remove("is-active");
        el.setAttribute("stroke-width", el.getAttribute("data-orig-sw") || "1.5");
      }
    }

    // ATUALIZA ITEM ATIVO NA LISTA DO PAINEL
    var allItems = document.querySelectorAll("#a12p22b-svg .a12p22b-item");
    for (var j = 0; j < allItems.length; j++) {
      var item = allItems[j];
      if (item.getAttribute("data-id") === id) {
        item.classList.add("is-active");
      } else {
        item.classList.remove("is-active");
      }
    }
  }

  // ATTACH CLICK & KEYBOARD EVENTS NAS ESTRUTURAS
  var hsList = document.querySelectorAll("#a12p22b-svg .a12p22b-hs");
  for (var k = 0; k < hsList.length; k++) {
    (function(hs) {
      var id = hs.getAttribute("data-id");
      hs.setAttribute("data-orig-sw", hs.getAttribute("stroke-width") || "1.5");

      hs.addEventListener("click", function() {
        hs.classList.add("is-revealed");
        updatePanel(id);
      });

      hs.addEventListener("keydown", function(e) {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          hs.classList.add("is-revealed");
          updatePanel(id);
        }
      });
    })(hsList[k]);
  }

  // ATTACH EVENTS NOS ITENS DA LISTA DO PAINEL
  var itemList = document.querySelectorAll("#a12p22b-svg .a12p22b-item");
  for (var m = 0; m < itemList.length; m++) {
    (function(it) {
      var id = it.getAttribute("data-id");
      it.addEventListener("click", function() {
        var targetHs = document.querySelector("#a12p22b-svg .a12p22b-hs[data-id='" + id + "']");
        if (targetHs) targetHs.classList.add("is-revealed");
        updatePanel(id);
      });
    })(itemList[m]);
  }

  // CONTROLE DE MODOS (PREENCHIDO, SEM ROTULOS, CONFERENCIA)
  var svgRoot = document.getElementById("a12p22b-svg");
  var btnFull = document.getElementById("a12p22b-btn-full");
  var btnUnlabeled = document.getElementById("a12p22b-btn-unlabeled");
  var btnConference = document.getElementById("a12p22b-btn-conference");

  function setMode(mode) {
    if (!svgRoot) return;
    svgRoot.setAttribute("data-mode", mode);

    var bgFull = document.getElementById("a12p22b-btn-full-bg");
    var txFull = document.getElementById("a12p22b-btn-full-tx");
    var bgUn = document.getElementById("a12p22b-btn-unlabeled-bg");
    var txUn = document.getElementById("a12p22b-btn-unlabeled-tx");
    var bgConf = document.getElementById("a12p22b-btn-conference-bg");
    var txConf = document.getElementById("a12p22b-btn-conference-tx");

    if (mode === "full") {
      bgFull.setAttribute("fill", "var(--a12p22b-fascia)");
      txFull.setAttribute("fill", "#FFFFFF");
      bgUn.setAttribute("fill", "var(--a12p22b-panel-bg)");
      txUn.setAttribute("fill", "var(--a12p22b-text-muted)");
      bgConf.setAttribute("fill", "var(--a12p22b-panel-bg)");
      txConf.setAttribute("fill", "var(--a12p22b-text-muted)");
    } else if (mode === "unlabeled") {
      bgFull.setAttribute("fill", "var(--a12p22b-panel-bg)");
      txFull.setAttribute("fill", "var(--a12p22b-text-muted)");
      bgUn.setAttribute("fill", "var(--a12p22b-membrana)");
      txUn.setAttribute("fill", "#FFFFFF");
      bgConf.setAttribute("fill", "var(--a12p22b-panel-bg)");
      txConf.setAttribute("fill", "var(--a12p22b-text-muted)");
    } else if (mode === "conference") {
      bgFull.setAttribute("fill", "var(--a12p22b-panel-bg)");
      txFull.setAttribute("fill", "var(--a12p22b-text-muted)");
      bgUn.setAttribute("fill", "var(--a12p22b-panel-bg)");
      txUn.setAttribute("fill", "var(--a12p22b-text-muted)");
      bgConf.setAttribute("fill", "var(--a12p22b-perineo)");
      txConf.setAttribute("fill", "#FFFFFF");
    }
  }

  if (btnFull) {
    btnFull.addEventListener("click", function() { setMode("full"); });
    btnFull.addEventListener("keydown", function(e) { if (e.key === "Enter" || e.key === " ") setMode("full"); });
  }
  if (btnUnlabeled) {
    btnUnlabeled.addEventListener("click", function() { setMode("unlabeled"); });
    btnUnlabeled.addEventListener("keydown", function(e) { if (e.key === "Enter" || e.key === " ") setMode("unlabeled"); });
  }
  if (btnConference) {
    btnConference.addEventListener("click", function() { setMode("conference"); });
    btnConference.addEventListener("keydown", function(e) { if (e.key === "Enter" || e.key === " ") setMode("conference"); });
  }

  // INICIALIZA PAINEL E MODOS
  updatePanel("puborretal");
  setMode("full");
})();
